/* @lc app=leetcode id=1942 lang=kotlin */ class Solution { fun smallestChair(times: Array<IntArray>, targetFriend: Int): Int = java.util.PriorityQueue<Int>().let { freeChairs -> intArrayOf(0).let { nextChair -> IntArray(times.size).let { occupied -> times.indices.flatMap { i -> listOf(Triple(times[i][0], 1, i), Triple(times[i][1], 0, i)) }.sortedWith(compareBy<Triple<Int, Int, Int>> { it.first }.thenBy { it.second }).firstNotNullOf { (time, type, friend) -> if (type == 1) { (if (freeChairs.isNotEmpty()) freeChairs.poll() else nextChair[0].also { nextChair[0]++ }).also { occupied[friend] = it }.takeIf { friend == targetFriend } } else { freeChairs.add(occupied[friend]).run{null} } } } } }}